nosql_query:
db.Dogs.aggregate(
[
  {
    "$match": {
      "age": {
        "$lt": "( SELECT avg(age) FROM Dogs )"
      }
    }
  },
  {
    "$group": {
      "_id": null,
      "count": {
        "$sum": 1
      }
    }
  }
]
)

